@property UILabel *status;
@property UIButton *install;
@end
@implementation TAPReview
- (void)viewDidLoad{[super viewDidLoad];self.title=_package[@"document"][@"name"];self.view.backgroundColor=TIOPaper();self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;
 UINavigationBarAppearance *appearance=[UINavigationBarAppearance new];[appearance configureWithDefaultBackground];appearance.backgroundColor=TIOPaper();appearance.titleTextAttributes=@{NSForegroundColorAttributeName:TIOInk()};self.navigationItem.standardAppearance=appearance;self.navigationItem.scrollEdgeAppearance=appearance;
 _preview=[TAPPreview new];_preview.document=_package[@"document"];_preview.layer.cornerRadius=12;_preview.clipsToBounds=YES;[_preview.heightAnchor constraintEqualToAnchor:_preview.widthAnchor multiplier:180.0/540].active=YES;
 NSMutableArray *names=[NSMutableArray new];for(NSDictionary *p in _package[@"document"][@"pages"])[names addObject:p[@"id"]];UISegmentedControl *pages=[[UISegmentedControl alloc]initWithItems:names];pages.selectedSegmentIndex=0;[pages addTarget:self action:@selector(page:) forControlEvents:UIControlEventValueChanged];
 UILabel *info=[UILabel new];info.numberOfLines=0;info.font=[UIFont systemFontOfSize:14];info.textColor=TIOInk();info.text=[NSString stringWithFormat:@"%@ · v%@\n%lu 页 · %@ 字节（解压）\n540 × 180 原生组件预览，字体以镜片为准。\n权限：%@\nZIP SHA-256\n%@",_package[@"document"][@"id"],_package[@"document"][@"version"],(unsigned long)names.count,_package[@"unpackedBytes"],[_package[@"document"][@"permissions"]count]?@"后端按钮事件（此版尚不外发）":@"无网络、麦克风或定位权限",_package[@"zipSHA256"]];
 UIButton *query=[UIButton buttonWithType:UIButtonTypeSystem];[query setTitle:@"查询眼镜当前槽位" forState:UIControlStateNormal];[query addTarget:self action:@selector(query) forControlEvents:UIControlEventTouchUpInside];TIOStyleAction(query,NO,NO);[query.heightAnchor constraintEqualToConstant:48].active=YES;
 _install=[UIButton buttonWithType:UIButtonTypeSystem];[_install setTitle:@"确认安装这个应用" forState:UIControlStateNormal];[_install addTarget:self action:@selector(confirm) forControlEvents:UIControlEventTouchUpInside];TIOStyleAction(_install,YES,NO);[_install.heightAnchor constraintEqualToConstant:50].active=YES;
 _status=[UILabel new];_status.numberOfLines=0;_status.font=[UIFont systemFontOfSize:14];_status.textColor=TIOInk();
 UIScrollView *scroll=[UIScrollView new];scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];[NSLayoutConstraint activateConstraints:@[[scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.bottomAnchor],[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor]]];UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[_preview,pages,info,query,_install,_status]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=18;stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:20],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-24],[stack.leadingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.trailingAnchor constant:-20]]];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(refresh) name:@"TAPPhoneChanged" object:nil];[self refresh];}
- (void)dealloc{[NSNotificationCenter.defaultCenter removeObserver:self];}
- (void)refresh{_status.text=TAPPhoneBridge.shared.note;_install.enabled=TAPPhoneBridge.shared.ready;}
- (void)page:(UISegmentedControl *)s{_preview.page=s.selectedSegmentIndex;}
- (void)query{[TAPPhoneBridge.shared query];}
- (void)confirm{TAPPhoneBridge *b=TAPPhoneBridge.shared;if(!b.ready){Notice(self,@"先查询当前眼镜的槽位状态。");return;}NSString *peer=[b.peer copy];NSDictionary *snapshot=b.snapshot,*package=_package;UIAlertController *a=[UIAlertController alertControllerWithTitle:@"安装到当前眼镜？" message:@"只安装此预览包，不刷固件。最多四个应用；相同 ID 仅允许更高版本更新。请让眼镜回首页并结束其他任务。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"确认安装" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){if(!b.ready||![b.peer isEqual:peer]||![b.snapshot isEqual:snapshot]){Notice(self,@"会话状态已变化，请重新查询和确认。");return;}[b install:package];}]];[self presentViewController:a animated:YES completion:nil];}
@end
