@implementation TAPLibrary
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];UIView *h=self.tableView.tableHeaderView;CGFloat w=self.tableView.bounds.size.width;h.frame=CGRectMake(0,0,w,176);NSArray<UIView *> *v=h.subviews;if(v.count>=3){v[0].frame=CGRectMake(20,12,w-40,36);v[1].frame=CGRectMake(20,54,w-40,48);_tabs.frame=CGRectMake(20,120,w-40,38);}}
- (void)viewDidLoad{[super viewDidLoad];self.title=@"应用广场";self.mode=1;TIOStyleResearchTable(self);UIView *h=[[UIView alloc]initWithFrame:CGRectMake(0,0,360,176)];UILabel *title=[[UILabel alloc]initWithFrame:CGRectMake(20,12,320,36)];title.autoresizingMask=UIViewAutoresizingFlexibleWidth;title.text=@"把想法，戴在眼前。";title.font=[UIFont systemFontOfSize:25 weight:UIFontWeightSemibold];title.textColor=TIOInk();[h addSubview:title];UILabel *detail=[[UILabel alloc]initWithFrame:CGRectMake(20,54,320,48)];detail.autoresizingMask=UIViewAutoresizingFlexibleWidth;detail.text=@"20 个 MCP 灵感模板\n连接你自己的 Server，创造自己的小应用。";detail.numberOfLines=2;detail.textColor=UIColor.secondaryLabelColor;detail.font=[UIFont systemFontOfSize:14];[h addSubview:detail];_tabs=[[UISegmentedControl alloc]initWithItems:@[@"我的应用",@"应用广场",@"开发指南"]];_tabs.frame=CGRectMake(20,120,320,38);_tabs.autoresizingMask=UIViewAutoresizingFlexibleWidth;_tabs.selectedSegmentIndex=1;_tabs.selectedSegmentTintColor=[TIOAccent()colorWithAlphaComponent:.20];[_tabs addTarget:self action:@selector(switchTab:) forControlEvents:UIControlEventValueChanged];_tabs.accessibilityIdentifier=@"apps-sections";[h addSubview:_tabs];self.tableView.tableHeaderView=h;[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(refresh) name:@"TAPPhoneChanged" object:nil];}
- (void)querySlotsOnEntry{if(_mode==0&&!_importing&&!TAPPhoneBridge.shared.busy)[TAPPhoneBridge.shared query];}
- (void)switchTab:(UISegmentedControl *)tabs{self.mode=tabs.selectedSegmentIndex;[self refresh];[self.tableView setContentOffset:CGPointMake(0,-self.tableView.adjustedContentInset.top) animated:NO];[self querySlotsOnEntry];}
