- (void)viewWillAppear:(BOOL)a{[super viewWillAppear:a];UILabel *label=[UILabel new];label.text=self.title;label.textColor=TIOInk();label.font=[UIFont systemFontOfSize:17 weight:UIFontWeightSemibold];[label sizeToFit];self.navigationItem.titleView=label;[self refresh];}
