- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p{UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];TIOStyleResearchCell(c);c.detailTextLabel.numberOfLines=2;TAPPhoneBridge *b=TAPPhoneBridge.shared;
 if(_mode==2){c.textLabel.text=@[@"复制完整开发任务",@"复制 Skill 安装命令",@"仪表盘与 App SDK 文档",@"Server 与发布边界"][p.row];c.detailTextLabel.text=@[@"交给 Agent：开发、打包、校验、导入",@"由你确认后安装到自己的 Agent",@"API、Schema、ZIP、测试与 GitHub 分发",@"查看快照更新、权限和已知限制"][p.row];c.imageView.image=[UIImage systemImageNamed:@[@"doc.on.doc",@"terminal",@"book.closed",@"server.rack"][p.row]];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
 if(_mode==1){NSDictionary *item=p.section?GalleryItems()[p.row]:Builtins()[p.row];c.textLabel.text=item[@"name"];c.detailTextLabel.text=p.section?[NSString stringWithFormat:@"%@ · 离线模板\n%@",item[@"category"],item[@"purpose"]]:item[@"detail"];c.detailTextLabel.numberOfLines=3;c.accessibilityIdentifier=[(p.section?@"recipe-":@"builtin-")stringByAppendingString:p.section?item[@"id"]:item[@"resource"]];if(p.section){c.imageView.image=[UIImage systemImageNamed:item[@"symbol"]]?:[UIImage systemImageNamed:@"app"] ;c.imageView.tintColor=TIOAccent();c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}else{NSDictionary *pkg=BuiltinPackage(p.row,nil);TAPPreview *preview=[[TAPPreview alloc]initWithFrame:CGRectMake(0,0,108,36)];preview.document=pkg[@"document"];preview.layer.cornerRadius=5;preview.clipsToBounds=YES;c.accessoryView=preview;}return c;}
 if(!p.section){c.textLabel.text=p.row?(_importing?@"正在校验…":@"导入应用 ZIP"):(b.busy?@"正在等待眼镜…":@"查询四槽状态");c.detailTextLabel.text=p.row?@"预览每页、核对权限与 SHA-256 后安装":@"只读查询，不启动应用、不自动刷固件";c.imageView.image=[UIImage systemImageNamed:p.row?@"square.and.arrow.down":@"arrow.clockwise"];}else{id row=b.snapshot?b.snapshot[@"slots"][p.row]:nil;BOOL live=[row isKindOfClass:NSDictionary.class]&&![row[@"tombstone"]boolValue];c.textLabel.text=live?row[@"name"]:[NSString stringWithFormat:@"槽位 %ld · %@",(long)p.row+1,b.snapshot?@"空闲":@"未读取"];c.detailTextLabel.text=live?[NSString stringWithFormat:@"%@ · v%@%@",row[@"id"],row[@"version"],[b.snapshot[@"activeSlot"]integerValue]==p.row?@" · 正在运行":@""]:@"从手机导入，眼镜“我的应用”中打开";c.imageView.image=[UIImage systemImageNamed:live?@"app.dashed":@"plus.app"];c.accessoryType=live?UITableViewCellAccessoryDisclosureIndicator:UITableViewCellAccessoryNone;}return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p{[t deselectRowAtIndexPath:p animated:YES];if(_mode==2){if(p.row==0)CopyPrompt(self,DeveloperPrompt());else if(p.row==1)CopyPrompt(self,@"npx skills add Turbo1123/Turbo-IO --skill turboio-developer -g");else if(p.row==2)[UIApplication.sharedApplication openURL:[NSURL URLWithString:@"https://github.com/Turbo1123/Turbo-IO/blob/main/docs/DEVELOPER_ECOSYSTEM.md"] options:@{} completionHandler:nil];else Notice(self,@"用户 Server 连接 MCP → 白名单展示字段 → 仪表盘 API 或 App ZIP → 手机批准 → 眼镜。App v1 为手动安装的数据快照；自动更新和按钮事件回流尚未接通。不要把 GitHub 当作私有数据/密钥仓库。");return;}if(_mode==1){if(p.section){TAPRecipe *v=[[TAPRecipe alloc]initWithStyle:UITableViewStyleInsetGrouped];v.item=GalleryItems()[p.row];[self.navigationController pushViewController:v animated:YES];}else{NSString *error=nil;NSDictionary *package=BuiltinPackage(p.row,&error);if(!package){Notice(self,error?:@"此构建未附带示例包。");return;}TAPReview *review=[TAPReview new];review.package=package;[self.navigationController pushViewController:review animated:YES];}return;}TAPPhoneBridge *b=TAPPhoneBridge.shared;if(b.busy||_importing){Notice(self,@"当前操作尚未完成，请等待。");return;}if(!p.section){if(!p.row){[b query];return;}UIDocumentPickerViewController *picker=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeZIP] asCopy:NO];picker.delegate=self;picker.allowsMultipleSelection=NO;[self presentViewController:picker animated:YES completion:nil];return;}
 id row=b.snapshot?b.snapshot[@"slots"][p.row]:nil;if(![row isKindOfClass:NSDictionary.class]||[row[@"tombstone"]boolValue])return;if(!b.ready){Notice(self,@"先重新查询眼镜槽位。");return;}NSString *peer=[b.peer copy];unsigned slot=(unsigned)p.row;UIAlertController *a=[UIAlertController alertControllerWithTitle:row[@"name"] message:@"控制当前槽位中的这一版本；不会影响其他应用。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];
 for(NSNumber *n in @[@3,@4,@5]){unsigned op=n.unsignedIntValue;[a addAction:[UIAlertAction actionWithTitle:op==3?@"在眼镜打开":op==4?@"停止这个应用":@"卸载这个应用" style:op==5?UIAlertActionStyleDestructive:UIAlertActionStyleDefault handler:^(UIAlertAction *x){if(![peer isEqual:b.peer]){Notice(self,@"设备变化，未发送。");return;}[b operate:op slot:slot expected:row];}]];}[self presentViewController:a animated:YES completion:nil];}
- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{if(urls.count!=1||_importing)return;_importing=YES;[self refresh];NSURL *url=urls[0];__weak typeof(self) weak=self;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{BOOL scoped=[url startAccessingSecurityScopedResource];__block NSData *zip=nil;NSFileCoordinator *coordinator=[[NSFileCoordinator alloc]initWithFilePresenter:nil];[coordinator coordinateReadingItemAtURL:url options:0 error:nil byAccessor:^(NSURL *file){NSFileHandle *h=[NSFileHandle fileHandleForReadingFromURL:file error:nil];@try{zip=[h readDataUpToLength:24577 error:nil];}@finally{[h closeAndReturnError:nil];}}];if(scoped)[url stopAccessingSecurityScopedResource];NSString *error=nil;NSDictionary *package=TAPReadPackage(zip,&error);dispatch_async(dispatch_get_main_queue(),^{TAPLibrary *s=weak;if(!s)return;s.importing=NO;[s refresh];if(!s.view.window)return;if(!package){Notice(s,error?:@"读取失败。请先把文件下载到本机后重试。");return;}TAPReview *review=[TAPReview new];review.package=package;[s.navigationController pushViewController:review animated:YES];});});}
@end
